def final_price(price, discount_pct):
    """Price after a percentage discount, rounded to cents."""
    return round(price * (1 - discount_pct / 100), 2)

from pricing import final_price


def test_discount_applies():
    assert final_price(100, 10) == 90.0


def test_small_discount():
    assert final_price(200, 3) == 194.0


def test_discounts_are_capped_at_five_percent():
    assert final_price(100, 10) == 95.0

